func (p *Proxy) noRedirectClient() *http.Client {
	var transport http.RoundTripper
	if p.client != nil {
		transport = p.client.Transport
	}
	return &http.Client{
		Transport: transport,
		CheckRedirect: func(*http.Request, []*http.Request) error {
			return http.ErrUseLastResponse
		},
	}
}

